@lru_cache(maxsize=1)
def get_rg_logo_png_bytes() -> bytes:
    """Return the decoded RG logo PNG bytes."""
    return base64.b64decode(_RG_LOGO_BASE64)


@lru_cache(maxsize=1)
def get_rg_logo_data_url() -> str:
    """Return a data URL for the RG logo image."""
    return "data:image/png;base64," + _RG_LOGO_BASE64.replace("\n", "")


@lru_cache(maxsize=1)
def get_rg_logo_iframe_html() -> str:
    """Return HTML markup that renders the RG logo within an iframe."""
    srcdoc = (
        '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
        '<style>html,body{margin:0;background:transparent;overflow:hidden;}'
        'body{display:flex;align-items:center;justify-content:center;}'
        'img{display:block;width:100%;height:100%;object-fit:contain;}'
        '</style></head><body>'
        '<img src="' + get_rg_logo_data_url() + '" alt="RamGobbler Logo">'
        '</body></html>'
    )
    return (
        '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
        '<style>html,body{margin:0;background:transparent;overflow:hidden;}'
        'iframe{border:none;width:100%;height:100%;background:transparent;}'
        '</style></head><body>'
        '<iframe srcdoc="' + srcdoc.replace('"', '&quot;') + '" '
        'title="RamGobbler Logo" sandbox="allow-same-origin allow-scripts" '
        'scrolling="no"></iframe></body></html>'
    )
